// Parse Yahoo Finance chart data and run a Monte Carlo projection.
const input = $input.first().json;
const body = input.body || input;
const chart = body.chart && body.chart.result && body.chart.result[0];
if (!chart) throw new Error('No chart data returned for ticker');

const quotes = chart.indicators.quote[0];
const close = (quotes.close || []).filter((v) => v != null);
if (close.length < 12) throw new Error('Insufficient price history');

// Monthly log returns
const returns = [];
for (let i = 1; i < close.length; i++) {
  if (close[i] > 0 && close[i - 1] > 0) {
    returns.push(Math.log(close[i] / close[i - 1]));
  }
}
const n = returns.length;
const mean = returns.reduce((a, b) => a + b, 0) / n;
const variance = returns.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1);
const vol = Math.sqrt(variance) * Math.sqrt(12); // annualized
const drift = (mean * 12) + (vol * vol) / 2;      // GBM drift (monthly->annual)

const capital = Number($json.capital || 10000);
const years = Number($json.horizonYears || 10);
const paths = Number($json.simulations || 10000);

const rng = () => {
  // Box-Muller normal sample
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
};

const ends = [];
for (let p = 0; p < paths; p++) {
  let price = 1;
  for (let m = 0; m < years * 12; m++) {
    price *= Math.exp(drift / 12 - (vol * vol) / 24 + (vol / Math.sqrt(12)) * rng());
  }
  ends.push(capital * price);
}
ends.sort((a, b) => a - b);
const p = (q) => ends[Math.min(ends.length - 1, Math.floor(q * ends.length))];
const median = p(0.5);
const p10 = p(0.1);
const p90 = p(0.9);
const annualized = Math.pow(median / capital, 1 / years) - 1;

const lastPrice = close[close.length - 1];
return [{
  json: {
    userId: $json.userId,
    ticker: $json.ticker,
    lastPrice,
    annualizedVol: vol,
    projection: {
      medianEnd: Math.round(median),
      p10: Math.round(p10),
      p90: Math.round(p90),
      annualizedReturn: Math.round(annualized * 10000) / 10000,
      allocation: { equities: 0.7, bonds: 0.2, cash: 0.1 },
      horizonYears: years,
      simulatedPaths: paths
    },
    notes: 'Monte Carlo projection from trailing 10y monthly history. Educational only - not investment advice.'
  }
}];
